      "AIは、学習したデータの傾向を映します。過去の採用データをそのまま学ばせれば、これまでの偏りを再生産しかねません。特定の属性が有利・不利になる傾向が過去にあれば、その偏りを引き継いだ整理を返す可能性があります。AIの出力は中立に見えても、中身が中立とは限らないという前提で扱います。",
