      "- 費用対効果（比率）：一定期間の効果の累計を、同じ期間の投資額で割る\n- 回収期間：初期費用を、月あたりの純効果で割り、何か月で元が取れるかを見る\n- 純効果：金額換算した効果から、その月にかかる運用費を差し引いた残り",
      "この3つを分けて出すと、投資の是非を数字で語れるようになります。以降では、効果の金額換算、費用の洗い出し、回収期間の計算という順に進めます。",
      "## 効果を金額に換算する（時間×人件費単価）",
