      "売上増のように不確実性の高い効果は、削減工数とは別枠で示し、時間削減の金額に混ぜません。混ぜると、確実な削減効果まで前提の弱い数字に引きずられ、試算全体の信頼が下がります。削減工数を金額にそろえる考え方は[ROI可視化フレーム](/magazine/roi-visualization)でも扱っています。",
      "## 初期費用と運用費を洗い出す",
