      "- 初期費用（一度きり）：設計・開発・データ整備・導入支援の合計\n- 運用費（毎月）：ツール利用料・従量課金・保守・運用人件費の合計\n- 見落としやすい項目：データ整備の工数と、社内の運用担当が使う時間",
