      "- 中立：削減1時間、月100件で効果30万円、回収12か月（先の例）\n- 弱気：削減が0.6時間にとどまると効果18万円、純効果13万円、回収はおよそ23か月\n- 強気：削減1時間で件数が130件に増えると効果39万円、純効果34万円、回収はおよそ9か月",
