      "- 運用費を入れ忘れる：初期費用だけで回収を語り、毎月の利用料や運用人件費を計算から落とす\n- 削減時間を理論値で置く：現場の実態ではなく、うまくいった場合の最大値で見積もる\n- 浮いた時間を効果に数える一方で、その時間が別の付加価値を生んでいるかを確かめない\n- 導入前の基準値がなく、削減幅を導入後の記憶から逆算してしまう",
