      "5つが欠けたガイドラインは、現場で「結局どうすればいいのか」という質問を生みます。とくに承認された利用窓口の指定は見落とされがちで、窓口がないまま「気をつけて使うこと」とだけ書くと、社員は手元の個人アカウントを使い続けます。",
