      "- 現状を把握する：社員がいま何のツールをどんな業務で使っているかを聞き取り、実態に合わせる\n- 線引きと窓口を決める：機密度の分類、承認する業務用ツール、確認責任の段階を先に固める\n- 短い版を作る：A4数枚に収め、具体例中心で書く。読まれない長文の規程集にしない\n- 周知して運用に乗せる：配って終わりにせず、相談先と報告のルートまで併せて伝える",
