      "防ぐ鍵は、安全に使える正規の窓口を用意し、そこに利用を集めることにあります。承認された業務用ツールを一つ定め、入力してよい情報の具体例と併せて示せば、社員はわざわざ隠れて使う理由がなくなります。禁止事項を並べるより、安全な使い方の見本を示すほうが定着します。",
