      "- 定型質問の一次対応：よくある質問に、根拠となる情報をもとに自動で回答する\n- 時間外の受付：夜間や休日でも一次回答を返し、顧客を待たせない\n- 履歴を踏まえた案内：注文番号や契約状況を参照し、状況に合った返答を返す\n- 入口での振り分け：AIで片づく問い合わせと、人が要る問い合わせを受付時点で仕分ける",
