      "作るものの水準は、おおまかに3段階で捉えると整理しやすくなります。段階が上がるほど、初期費用も運用の手間も増えていきます。",
      "- 既製ツールをそのまま使う：契約して設定するだけで、費用は月額が中心になる\n- 既製ツールを自社向けに調整する：データ連携や権限設定、テンプレート整備が加わる\n- 自社業務に合わせて内製する：要件定義から設計・開発まで行い、初期費用が主役になる",
