      "- 要件定義・設計：どの業務を、どこまで自動化するかを決める工程\n- 開発またはツール設定：モデルの組み込み、画面や連携の構築、既製ツールの初期設定\n- データ整備：社内に散らばる資料や履歴を、AIが使える形に整える作業\n- 導入支援・教育：現場が使えるようにするマニュアル作成や初期トレーニング",
      "この中で読み違えやすいのがデータ整備です。手元のデータが整っていれば軽く済みますが、紙やばらばらの形式で眠っている場合は、ここが初期費用の大きな部分を占めます。見積もりを取る前に、自社のデータがどの状態にあるかを確かめておくと、金額のぶれを減らせます。",
      "## 運用費の内訳：毎月積み上がるもの",
