      "- 利用料：ツールの月額や、AIモデルを呼び出すごとにかかるAPIの従量課金\n- インフラ費：サーバーやストレージなど、動かし続けるための基盤費用\n- 保守・改善：不具合対応や、使ううちに出てくる調整の工数\n- 運用担当の人件費：社内で管理・運用する人の時間",
