      "- 対象範囲：1業務だけか、複数部門にまたがるか\n- カスタムの深さ：既製のまま使うか、自社データ・自社フローに作り込むか\n- データの状態：使える形に整っているか、整備から着手するか\n- 連携の複雑さ：既存の基幹システムやSaaSと繋ぐ必要があるか",
