      "逆のパターンもあります。初期費用のかかる内製は高く見えても、毎月の利用料が発生しないため、TCOでは一定期間で逆転することがあります。どちらが自社に向くかは、対象業務が差別化に直結するか、既製で足りるかで変わります。分かれ目の整理は[内製とSaaSの判断フレーム](/magazine/inhouse-vs-saas)で扱っています。",
