      "※業種別の数値は代表的なシミュレーションであり、効果を保証するものではありません。",
      "当研究所では、この現状把握から費用対効果の試算までを無料の経営診断で行っています。金額の当たりをつけたい段階でも、まずは現状を数字にすることから始めてください。詳しくは[無料相談](/contact)をご利用ください。",
