      "- 対象経費：使いたい費目（ツール利用料・開発費・設備費・外注費など）が補助対象に入っているか\n- 補助率と自己負担：上限額だけでなく補助率（何割補助されるか）を見る。補助率1/2なら残り半分は自己負担\n- 要件とのフィット：従業員規模・業種・賃上げなどの要件に、自社の計画が無理なく収まるか\n- スケジュール：公募期間と交付決定の時期が、自社の導入計画と合うか。締切は制度ごとに異なる",
      "## 申請でつまずきやすい3点",
