      "- SaaS導入：完成したサービスを月額などで借りる。すぐ使え、保守やアップデートは提供元が担う。半面、機能は提供元の仕様に縛られ、利用料は使う人数と期間に比例して積み上がる\n- 内製：自社の業務に合わせて仕組みを作る。初期投資と保守責任を負う代わりに、機能を自社最適にでき、人数連動の利用料という固定費から解放される",
      "整理すると、SaaSは早さと手軽さを、内製は自由度と長期のコスト構造を取りに行く選択です。この違いを踏まえたうえで、どの業務をどちらに寄せるかを次の軸で判断します。",
      "## 判断を分ける4つの軸",
