      "- 標準性：どの会社もほぼ同じやり方で回る業務か、自社固有のやり方かを見る。会計処理や勤怠管理は標準的でSaaSで足り、自社独自の与信ルールや見積ロジックは固有度が高い\n- 競争力への直結度：その業務の巧拙が自社の強みや差別化に効くかを見る。経費精算は差がつきにくく、顧客データを使った提案の精度は直接売上に効く\n- スピード要求：来週から動かしたいのか、時間をかけて磨きたいのかを見る。今すぐ必要ならSaaSが速く、じっくり最適化したい領域は内製が向く\n- 規模と継続性：使う人数と頻度が多く、長く使い続けるかを見る。少人数の一時利用ならSaaS、全社の数百人が毎日使い続ける業務は人数連動の利用料が重くのしかかる",
