      "- SaaS側を積む：月額に利用人数と12ヶ月を掛け、比較する年数（たとえば3〜5年）分を並べる。将来の値上げやアカウント増を保守的に織り込む\n- 内製側を積む：初期の開発費に、運用の年額（インフラ、モデルの利用料、改修と保守の工数）を足し、同じ年数分を並べる\n- 損益分岐の年を見る：内製は初年度が重く、SaaSは後年ほど累計が積み上がる。両者の累計が交差する年が、判断の分かれ目になる\n- 前提を動かして確かめる：利用人数が増える前提や、使う期間が延びる前提に変えたとき、どちらの総額が有利に振れるかを見る",
      "私たちの支援の現場では、利用人数が右肩上がりの業務ほど、この総額比較で内製側の分がよくなる傾向があります。反対に、人数が少なく先が読めない業務では、無理に内製せずSaaSで様子を見るほうが安全です。汎用SaaSの固定費を内製で圧縮する具体的な考え方は[汎用SaaSの固定費を内製で1/3にする考え方](/magazine/saas-cost-one-third)で扱っています。",
