      "既存のSaaSを捨てる必要もありません。会計や顧客管理のSaaSはそのまま残し、その先の差別化領域だけを内製の仕組みでつなぐ構成にすれば、置き換えのリスクを抑えながら独自性を足していけます。全面刷新ではなく、部分の付け替えで進めるのが安全です。",
      "## 内製の初期投資を抑える方法",
      "内製と聞くと高くつく印象がありますが、それはゼロから作った場合の話です。作る範囲を絞れば、初期投資は現実的な水準に収まります。",
      "- 開発済みのモジュールと実績のあるオープン技術を組み合わせ、自前で作る範囲を差別化部分だけに絞る\n- 最初から全業務を対象にせず、効果が読める一業務で小さく作り、成果を確かめてから横に広げる\n- 特定のモデルに縛らず差し替え可能な設計にし、モデルの価格改定や性能向上に振り回されないようにする",
