      "- 任せやすい（可逆）：情報収集と下調べ、資料やメール文面の初稿づくり、社内向けの要約や分類など、間違えても手前で差し戻して直せる業務\n- 人の確認を挟む（半可逆から不可逆）：対外的な確定文書の送付、金銭の伴う処理、契約や採用の判断など、外に出た後の修正が難しい業務\n- まだ難しい：長い期間にわたって文脈を保ち続ける業務や、曖昧な目標を自力で正しく定義し直す業務",
