      "まだ難しい領域が残る理由も、可逆性の裏返しで説明できます。長い期間にわたる案件では、途中で前提が変わっても文脈を保ち続ける必要があり、ずれが積み重なると後から戻しにくくなります。目標そのものが曖昧な業務も、AIが方向を取り違えたまま進むと、やり直しの範囲が広がります。こうした業務は、区切って人が節目を確認する形に分解してから任せます。",
