      "たとえば問い合わせ対応なら、回答文の作成まではエージェントに任せ、返信ボタンを押すのは人にする。仕入れの発注なら、候補の比較と起案まで任せ、発注確定は責任者の承認に残す。同じ業務でも、可逆な工程と不可逆な工程で権限を分けると、任せられる部分だけを安全に切り出せます。",
      "権限はデータの機密度とも結びつけます。外部に出してよい情報とそうでない情報を分け、機微なデータは自社環境の中で完結させる。誰の権限で、どこまでのデータに触れてよいかを最小限に保つほど、任せても崩れにくくなります。境界の引き方は [AIとデータ保護の考え方](/magazine/ai-data-security) を参照してください。",
