      "## 主要な4つのリスクと、それぞれの打ち手",
      "漏えいの経路は、大きく四つに整理できます。原因が違えば対応も違うため、まとめて塞ごうとせず一つずつ手当てします。",
      "- 学習への流用：入力したデータが外部サービス側の学習に使われる懸念。入力を学習に使わない契約形態のサービスを選ぶか、自社環境内で処理を完結させて回避する\n- 権限を越えた閲覧：本来アクセス権のない情報に、AI経由で触れてしまう経路。たとえば一般社員向けのAIが人事フォルダを参照できてしまう状態。AIが読める範囲に既存のアクセス権限をそのまま反映させる\n- 出力からの漏えい：AIの回答に想定外の機密が混ざり、社外や無関係な相手に届く経路。出力先と共有範囲を管理し、社外向けの文面は人が最終確認する\n- 入力の不用意な送信：社員が機密を個人アカウントの外部ツールへ貼り付ける経路。利用ガイドラインと、業務用の安全な窓口の整備で防ぐ",
