      "第二に、既存の権限管理との整合。「誰がどの情報を見てよいか」という線引きは、すでに人事や情報システムが決めています。AIの利用でそのルールを崩さず、人が見られない情報はAI経由でも見られないようにします。新しい権限体系を作り直すのではなく、いま動いている権限にAIを合わせるのが、破綻を防ぐ近道です。",
