      "- 分類：自社データを三つの機密度に仕分け、高機密の線引きを文章で残す\n- 権限：AIが参照する範囲を業務単位で決め、既存のアクセス権限に合わせる\n- 窓口：正規の業務用ツールを一つ定め、個人利用との線引きを社内に周知する\n- ルール：入力してよい情報・してはいけない情報を、具体例つきで示す\n- 記録と見直し：利用ログを残し、扱う範囲を広げる前に定期的に点検する",
