        a: "予約・受付対応、日々の記録や報告書の作成、利用者・家族からの定型的な問い合わせ対応、システムへの入力や転記といったバックオフィス事務に使えます。専門資格を必ずしも要さない一方で、専門職の時間を確実に奪っている領域です。",
