      "私たちの支援の現場でよく見るのは、契約更新のたびに「使っているか」ではなく「解約して困らないか」だけで判断してしまう失敗です。困らないと言い切るには利用ログを確認する必要がありますが、そこまで踏み込まないと、休眠席や重複契約はそのまま温存されます。棚卸しの最初の対象を「不安だから残している契約」に定めると、削減余地が見えやすくなります。",
      "## まず「1/3」を数字に分解する",
      "「1/3にする」は感覚ではなく、計算で確かめる対象です。手順はシンプルで、まず現在の年間コストを、席数×単価×12ヶ月で洗い出します。そこに、実際にログインしている席数と、配布したまま使われていない席数の内訳を重ねます。次に、内製した場合にかかる開発の初期投資と、月々の運用コスト（インフラ・保守）を見積もります。",
