      "かつて内製は「高くつく選択肢」でした。生成AIとオープン技術の進化で、その前提が変わっています。鍵は、ゼロから作らないことです。開発済みのモジュールと最先端のオープン技術を組み合わせれば、汎用SaaSが提供してきた機能の相当部分を、より軽い構造で実装できます。開発の初期投資はかかりますが、毎月の利用料という固定費が消えるため、一定期間で回収し、以降はコストが構造的に下がります。",
      "## どの契約から手をつけるか",
