      "## 3層フレーム：投資・活用・効果を分けて捉える",
      "- 投資の層：ライセンス費、内製開発費、運用にかかる工数。AIにいくら使っているか\n- 活用の層：誰が、どのツールを、どの業務で、どれだけ使っているか。ログイン率と主要機能の利用率で見る\n- 効果の層：削減した工数、短縮したリードタイム、増えた売上。業務の数字がどう動いたか",
      "多くの企業が見えているのは投資の層だけです。請求書は毎月届くので、支払額は把握しやすい。しかしROIの説明に必要なのは、3層の「接続」です。投資したツールが実際に使われているか（投資から活用）、使われた結果として業務の数字が動いたか（活用から効果）。この2つの接続のどちらかが切れている場所が、そのまま改善点になります。投資はあるのに活用がなければ、それは削るべきライセンスです。活用はあるのに効果が出ていなければ、業務の設計かツールの選定を見直す対象です。",
      "効果の大きさは業務によって変わります。たとえば金融・保険の書類処理では、代表的なシミュレーションで処理工数がおよそ6割減る想定を置いています。ただしこれは前提を置いた試算であり、自社の実際の効果は、導入前後を同じ物差しで比べて初めて確定します。どのツールが使われずに費用だけ発生しているかは、[使われないライセンスを見つける活用度診断](/magazine/license-audit)の手順で洗い出せます。",
      "※業種別の数値（/cases）は代表的なシミュレーションであり、効果を保証するものではありません。",
      "## 換算ルールを固定する",
      "効果の層を金額にそろえないと、役員会の議論はかみ合いません。基本の換算式は「削減時間 × 対象業務の人件費単価」です。ここで重視するのは、正確さより固定です。",
      "- 人件費単価は、対象業務を担う階層の平均で1つに決める（例：一般職の時間単価を全社共通の係数に置く）\n- 福利厚生や間接費を単価に含めるかを、あらかじめ決めて毎回そろえる\n- 売上増のような不確実性の高い効果は、削減工数とは別枠で示し、混ぜない",
      "単価の置き方に議論の余地はありますが、毎回同じルールで計算していれば、月ごと・ツールごとの比較には使えます。逆に、案件ごとに単価を変えると、数字が都合よく操作されているように見え、説得力を失います。換算ルールは一度決めたら文書化し、担当者が代わっても同じ計算結果になる状態にしておきます。",
      "## 導入前に基準値を取る",
      "導入後に振り返って推定した数字は、役員会では反論に耐えません。「本当にAIの効果か、繁忙期がずれただけではないか」という問いに答えられないからです。着手前の1カ月で、対象業務の工数と件数を実測しておきます。",
      "- 対象業務を1つに絞り、担当者に1カ月だけ作業時間を記録してもらう\n- 処理件数、1件あたりの平均時間、月間の残業時間を基準値として控える\n- 記録の粒度を業務単位でそろえ、後で導入後と同じ物差しで比べられるようにする",
      "この1カ月の手間を惜しむと、後からどれだけ効果を語っても推定の域を出ません。基準値があれば、導入前後を同じ物差しで並べた、誰が見ても同じ結論になる比較ができます。私たちの支援の現場でも、基準値を取った案件と取らなかった案件では、役員会での数字の通り方がはっきり分かれます。",
      "## 月次で同じフォーマットを続ける",
      "単発の成果報告は、その場では手応えがあっても、翌月には比較の基準を失います。投資・活用・効果の3層を、毎月同じ1枚で示す運用にします。並べる項目は固定します。",
      "- 投資：今月の費用と、前月からの増減\n- 活用：主要ツールのログイン率・利用率と、使われていない席の数\n- 効果：換算ルールで金額化した削減額と、売上系の指標の推移",
      "同じ枠を並べ続けると、役員会は個別ツールの当たり外れではなく、AI投資の全体をポートフォリオとして見られるようになります。効果の出た業務の隣へ横展開する、活用されない契約を解約するといった判断が、その場で下せます。この定点観測をどう回すかは、[PoCを成果につなげる進め方](/magazine/poc-to-results)もあわせて参考になります。",
      "## 役員会での見せ方",
      "数字がそろっても、見せ方でつまずくことがあります。役員会は細部ではなく判断を求める場です。次の点を押さえます。",
      "- 冒頭に結論を1行で置く（例：今四半期のAI関連費用はいくら、削減効果はいくら、活用されない席は何席）\n- 3層を1枚に収め、接続が切れている箇所を色や矢印で一目で分かるようにする\n- ツール単位ではなく、業務単位・意思決定単位でまとめる\n- 換算の前提を脚注に添え、効果を保証する数字ではないことを明示する",
      "避けたいのは、ツールの機能自慢と、精緻すぎる試算です。役員が知りたいのは、次にどこへ投資し、どこを止めるかです。その判断に必要な粒度まで丸めて出すほうが、議論は前に進みます。細部の正確さで信頼を得ようとするほど、判断は遅れます。",
      "## まとめ",
      "ROIの可視化は、説明責任を果たすためだけの作業ではありません。3層がつながって見えれば、削る所と伸ばす所が同じ画面で判断でき、次の一手を速く正しく打てます。まずは自社の現状を投資・活用・効果の3つに当てはめ、どの層が見えていないかを確かめるところからはじめてください。現状を3層で棚卸しし、役員会で使える形に整えたい方は、[無料相談](/contact)からご相談ください。",
