      "- 受領：メール添付やPDF、紙のスキャンをまとめて取り込む。様式は揃っていなくてよい\n- 読み取りと仕訳：請求元・金額・日付・費目をAIが抽出し、勘定科目の初稿を当てる\n- 突合：発注データや契約金額と自動で照合し、差異があれば印をつける\n- 承認：確信度が高いものは一覧で一括確認、低いものと差異ありは例外ルートで個別確認\n- 支払い：承認済みだけを支払データへ渡す",
